/**
 * Domain operations: pure functions AppData → AppData (+ a plain-language change
 * summary). The reducer in src/state only wires UI actions to these.
 *
 * Invariants every operation keeps:
 *  - completed / partial sessions are never moved or deleted by a replan;
 *  - quiz history is append-only (only deleting a topic or subject removes its checks);
 *  - future auto sessions are regenerated by the same scheduler everywhere.
 */
import type {
  AppData,
  Availability,
  ChangeSummary,
  DateKey,
  Familiarity,
  Importance,
  QuizResult,
  Session,
  Subject,
  SubjectColor,
  Topic,
} from '../types'
import { outcomeFromMinutes, pComplete, updateCompletion } from '../engine/completion'
import { ENGINE as E } from '../engine/config'
import { uid } from '../engine/ids'
import { initialMemory, updateFromQuiz } from '../engine/memory'
import {
  diffPlans,
  examFor,
  examStartAbs,
  isMissed,
  minuteShiftNote,
  replan,
  resolveMissedInData,
  sessionEndAbs,
  sortSessions,
} from '../engine/plan'
import { allInsights } from '../engine/insights'
import { validatePlacement } from '../engine/slots'
import { applyOps, type WhatIfOp } from '../engine/whatif'
import { momentToAbs, type LocalMoment } from '../engine/time'

export interface OpError {
  message: string
  field?: 'date' | 'time' | 'duration'
}

export interface OpOutput {
  data: AppData
  change: ChangeSummary | null
  error?: OpError
}

const fail = (data: AppData, message: string, field?: OpError['field']): OpOutput => ({
  data,
  change: null,
  error: { message, field },
})

// ---- Change summaries --------------------------------------------------------------

function futureOpen(data: AppData, nowAbs: number, ignore: readonly string[] = []): Session[] {
  return data.sessions.filter((s) => s.status === 'planned' && sessionEndAbs(s) > nowAbs && !ignore.includes(s.id))
}

/** "Newton's laws exam-day forecast: 88% → 86%" for the topics whose forecast moved most. */
function forecastShiftNote(oldData: AppData, newData: AppData, now: LocalMoment): string | undefined {
  const before = new Map(allInsights(oldData, now).map((i) => [i.topic.id, i]))
  const rows = allInsights(newData, now)
    .map((i) => ({ i, b: before.get(i.topic.id) }))
    .filter((r) => r.b && r.i.projectedWith !== null && r.b.projectedWith !== null)
    .map((r) => ({ name: r.i.topic.name, from: r.b!.projectedWith as number, to: r.i.projectedWith as number }))
    .filter((r) => Math.abs(r.to - r.from) >= 0.01)
    .sort((a, b) => Math.abs(b.to - b.from) - Math.abs(a.to - a.from))
    .slice(0, 2)
  if (rows.length === 0) return undefined
  const pct = (x: number) => `${Math.round(x * 100)}%`
  return `Exam-day forecast: ${rows.map((r) => `${r.name} ${pct(r.from)} → ${pct(r.to)}`).join(', ')}.`
}

export function summarizeChange(
  oldData: AppData,
  newData: AppData,
  now: LocalMoment,
  title: string,
  opts: { note?: string; canUndo?: boolean; ignoreIds?: string[]; skippedIds?: string[] } = {},
): ChangeSummary {
  const nowAbs = momentToAbs(now)
  const before = futureOpen(oldData, nowAbs, opts.ignoreIds)
  const after = futureOpen(newData, nowAbs)
  const topicName = (id: string) =>
    newData.topics.find((t) => t.id === id)?.name ?? oldData.topics.find((t) => t.id === id)?.name ?? 'A topic'
  const items = diffPlans(before, after, { topicName, today: now.date, skippedIds: opts.skippedIds })
  const shift = minuteShiftNote(before, after, topicName)
  const forecast = forecastShiftNote(oldData, newData, now)
  return {
    id: uid('chg'),
    title,
    items,
    note: [opts.note, shift, forecast].filter(Boolean).join(' ') || undefined,
    canUndo: opts.canUndo ?? true,
  }
}

function commit(
  old: AppData,
  mid: AppData,
  now: LocalMoment,
  title: string,
  opts: { note?: string; canUndo?: boolean; ignoreIds?: string[]; skippedIds?: string[] } = {},
): OpOutput {
  const { data } = replan(mid, now)
  return { data, change: summarizeChange(old, data, now, title, opts) }
}

// ---- Sessions ---------------------------------------------------------------------

export function skipSession(data: AppData, sessionId: string, now: LocalMoment): OpOutput {
  const s = data.sessions.find((x) => x.id === sessionId)
  if (!s || s.status !== 'planned') return fail(data, 'That session is no longer waiting on the plan.')
  const mid: AppData = {
    ...data,
    sessions: data.sessions.map((x) => (x.id === sessionId ? { ...x, status: 'skipped' as const } : x)),
    completion: updateCompletion(data.completion, s.durationMin, { kind: 'skipped' }),
    activeTimer: data.activeTimer?.sessionId === sessionId ? null : data.activeTimer,
  }
  const pBefore = Math.round(pComplete(data.completion, s.durationMin) * 100)
  const pAfter = Math.round(pComplete(mid.completion, s.durationMin) * 100)
  return commit(data, mid, now, 'Skipped. Plans change, and we can work with that.', {
    note: `Your estimated chance of finishing ${s.durationMin}-minute sessions moved from ${pBefore}% to ${pAfter}%, so Zuno plans a little buffer where it helps most.`,
    skippedIds: [sessionId],
  })
}

export function moveSession(
  data: AppData,
  sessionId: string,
  date: DateKey,
  startMin: number,
  now: LocalMoment,
  durationMin?: number,
): OpOutput {
  const s = data.sessions.find((x) => x.id === sessionId)
  if (!s || s.status !== 'planned') return fail(data, 'That session is no longer waiting on the plan.')
  const topic = data.topics.find((t) => t.id === s.topicId)
  const dur = durationMin ?? s.durationMin
  const check = validatePlacement({
    availability: data.availability,
    sessions: data.sessions,
    sessionId,
    date,
    startMin,
    durationMin: dur,
    examStartAbs: topic ? examStartAbs(examFor(data, topic)) : null,
    nowAbs: momentToAbs(now),
  })
  if (!check.ok) return fail(data, check.message ?? 'That time does not work.', check.field)
  // A moved session becomes a manual one: new id (the old auto id belongs to its slot),
  // and the day it left is remembered so the planner does not simply refill it.
  const newId = s.id.startsWith('auto|') ? uid('man') : s.id
  const vacated = [...new Set([...(s.vacated ?? []), ...(s.date !== date ? [s.date] : [])])].filter((d) => d !== date)
  const mid: AppData = {
    ...data,
    sessions: data.sessions.map((x) =>
      x.id === sessionId ? { ...x, id: newId, date, startMin, durationMin: dur, locked: true, vacated } : x,
    ),
    activeTimer: data.activeTimer?.sessionId === sessionId ? { ...data.activeTimer, sessionId: newId } : data.activeTimer,
  }
  const resized = dur !== s.durationMin
  return commit(data, mid, now, resized && date === s.date && startMin === s.startMin ? 'Session length updated.' : 'Session moved.', {
    note: 'You placed this session, so Zuno keeps it exactly where you put it and plans around it.',
  })
}

export function unlockSession(data: AppData, sessionId: string, now: LocalMoment): OpOutput {
  const s = data.sessions.find((x) => x.id === sessionId)
  if (!s || !s.locked) return { data, change: null }
  const mid: AppData = { ...data, sessions: data.sessions.map((x) => (x.id === sessionId ? { ...x, locked: false } : x)) }
  return commit(data, mid, now, 'Zuno is deciding this one again.')
}

export interface QuizInput {
  topicId: string
  sessionId?: string
  correct: number
  total: number
  source: QuizResult['source']
}

export const MAX_QUIZ_SIZE = 20

/** Record a recall check: updates the topic's memory estimate and appends to the quiz history. */
export function applyQuiz(
  data: AppData,
  q: QuizInput,
  nowAbs: number,
): { data: AppData; quiz: QuizResult } | { error: string } {
  const topic = data.topics.find((t) => t.id === q.topicId)
  if (!topic) return { error: 'That topic no longer exists.' }
  if (!Number.isInteger(q.total) || q.total < 1 || q.total > MAX_QUIZ_SIZE) {
    return { error: `Enter how many questions you answered (1 to ${MAX_QUIZ_SIZE}).` }
  }
  if (!Number.isInteger(q.correct) || q.correct < 0 || q.correct > q.total) {
    return { error: `Correct answers must be between 0 and ${q.total}.` }
  }
  const upd = updateFromQuiz(topic.memory, { correct: q.correct, total: q.total }, nowAbs, topic.struggling)
  const quiz: QuizResult = {
    id: uid('quiz'),
    topicId: q.topicId,
    sessionId: q.sessionId,
    atAbs: nowAbs,
    correct: q.correct,
    total: q.total,
    source: q.source,
    recallBefore: upd.recallBefore,
    recallAfter: upd.next.recall,
    stabilityBefore: upd.stabilityBefore,
    stabilityAfter: upd.stabilityAfter,
  }
  return {
    quiz,
    data: {
      ...data,
      topics: data.topics.map((t) => (t.id === q.topicId ? { ...t, memory: upd.next } : t)),
      quizzes: [...data.quizzes, quiz],
    },
  }
}

export interface FinishInput {
  sessionId: string
  actualMin: number
  startAbs: number
  quiz?: Omit<QuizInput, 'topicId' | 'sessionId'>
}

export interface FinishOutput extends OpOutput {
  quiz?: QuizResult
}

/**
 * Close out a session: record what actually happened, update the completion
 * model, and (if a recall check was done) the memory estimate. Then re-plan.
 */
export function finishSession(data: AppData, input: FinishInput, now: LocalMoment): FinishOutput {
  const s = data.sessions.find((x) => x.id === input.sessionId)
  if (!s || s.status !== 'planned') return fail(data, 'That session was already recorded.')
  const minutes = Math.max(0, Math.round(input.actualMin))
  const outcome = outcomeFromMinutes(s.durationMin, minutes)
  const status: Session['status'] =
    outcome.kind === 'completed' ? 'completed' : outcome.kind === 'partial' ? 'partial' : 'skipped'

  let working: AppData = {
    ...data,
    sessions: data.sessions.map((x) =>
      x.id === s.id ? { ...x, status, actual: status === 'skipped' ? undefined : { startAbs: input.startAbs, minutes } } : x,
    ),
    completion: updateCompletion(data.completion, s.durationMin, outcome),
    activeTimer: data.activeTimer?.sessionId === s.id ? null : data.activeTimer,
  }

  let quiz: QuizResult | undefined
  let note: string | undefined
  if (input.quiz && status !== 'skipped') {
    const applied = applyQuiz(working, { ...input.quiz, topicId: s.topicId, sessionId: s.id }, momentToAbs(now))
    if ('error' in applied) return fail(data, applied.error)
    working = {
      ...applied.data,
      sessions: applied.data.sessions.map((x) => (x.id === s.id ? { ...x, quizId: applied.quiz.id } : x)),
    }
    quiz = applied.quiz
    const name = data.topics.find((t) => t.id === s.topicId)?.name ?? 'this topic'
    const from = Math.round(quiz.recallBefore * 100)
    const to = Math.round(quiz.recallAfter * 100)
    note = `Your estimated recall for ${name} moved from ${from}% to ${to}% based on ${quiz.correct}/${quiz.total}.`
  } else if (status !== 'skipped') {
    note = 'No recall check was recorded, so Zuno kept your recall estimate as it was. Finishing a timer does not prove mastery.'
  }

  const out = commit(data, working, now, status === 'partial' ? 'Partial session saved.' : 'Session saved.', {
    note,
    canUndo: false,
    ignoreIds: [s.id],
  })
  return { ...out, quiz }
}

export function recordManualQuiz(data: AppData, q: Omit<QuizInput, 'source'>, now: LocalMoment): FinishOutput {
  const applied = applyQuiz(data, { ...q, source: 'manual' }, momentToAbs(now))
  if ('error' in applied) return fail(data, applied.error)
  const name = data.topics.find((t) => t.id === q.topicId)?.name ?? 'this topic'
  const out = commit(data, applied.data, now, 'Recall check saved.', {
    note: `Your estimated recall for ${name} moved from ${Math.round(applied.quiz.recallBefore * 100)}% to ${Math.round(applied.quiz.recallAfter * 100)}%.`,
    canUndo: false,
  })
  return { ...out, quiz: applied.quiz }
}

export const resolveMissed = resolveMissedInData

export function markMissedAsSkipped(data: AppData, now: LocalMoment): OpOutput {
  const nowAbs = momentToAbs(now)
  const count = data.sessions.filter((s) => isMissed(s, nowAbs)).length
  if (count === 0) return { data, change: null }
  return commit(data, resolveMissed(data, now), now, `${count} earlier ${count === 1 ? 'session' : 'sessions'} marked as skipped.`, {
    note: 'A good place to pick things back up.',
  })
}

// ---- Topics and subjects --------------------------------------------------------------

export function toggleStruggle(data: AppData, topicId: string, now: LocalMoment): OpOutput {
  const t = data.topics.find((x) => x.id === topicId)
  if (!t) return { data, change: null }
  const mid: AppData = {
    ...data,
    topics: data.topics.map((x) => (x.id === topicId ? { ...x, struggling: !x.struggling } : x)),
  }
  return commit(data, mid, now, t.struggling ? `${t.name} is no longer flagged.` : `${t.name} flagged. Zuno will give it extra attention.`)
}

const COLOR_ORDER: SubjectColor[] = ['blue', 'peach', 'mint', 'lilac', 'rose', 'sky', 'gold']
export const nextSubjectColor = (used: SubjectColor[]): SubjectColor =>
  COLOR_ORDER.find((c) => !used.includes(c)) ?? COLOR_ORDER[used.length % COLOR_ORDER.length]

export interface SubjectInput {
  id?: string
  name: string
  color?: SubjectColor
  examDate: DateKey
  examName?: string
}

export function saveSubject(data: AppData, input: SubjectInput, now: LocalMoment): OpOutput {
  const name = input.name.trim()
  if (!name) return fail(data, 'Give the subject a name.')
  let subjects = data.subjects
  let exams = data.exams
  const existing = input.id ? data.subjects.find((s) => s.id === input.id) : undefined
  let subject: Subject
  if (existing) {
    subject = { ...existing, name, color: input.color ?? existing.color }
    subjects = subjects.map((s) => (s.id === existing.id ? subject : s))
    const exam = exams.find((e) => e.subjectId === existing.id)
    if (exam) exams = exams.map((e) => (e.id === exam.id ? { ...e, date: input.examDate, name: input.examName ?? e.name } : e))
    else exams = [...exams, { id: uid('exam'), subjectId: existing.id, name: input.examName ?? `${name} exam`, date: input.examDate, startMin: E.DEFAULT_EXAM_START_MIN }]
  } else {
    subject = { id: uid('subj'), name, color: input.color ?? nextSubjectColor(data.subjects.map((s) => s.color)) }
    subjects = [...subjects, subject]
    exams = [...exams, { id: uid('exam'), subjectId: subject.id, name: input.examName ?? `${name} exam`, date: input.examDate, startMin: E.DEFAULT_EXAM_START_MIN }]
  }
  const exam = exams.find((e) => e.subjectId === subject.id)!
  const topics = data.topics.map((t) => (t.subjectId === subject.id ? { ...t, examId: exam.id } : t))
  return commit(data, { ...data, subjects, exams, topics }, now, existing ? `${name} updated.` : `${name} added.`)
}

export function deleteSubject(data: AppData, subjectId: string, now: LocalMoment): OpOutput {
  const topicIds = data.topics.filter((t) => t.subjectId === subjectId).map((t) => t.id)
  const mid: AppData = {
    ...data,
    subjects: data.subjects.filter((s) => s.id !== subjectId),
    exams: data.exams.filter((e) => e.subjectId !== subjectId),
    topics: data.topics.filter((t) => t.subjectId !== subjectId),
    sessions: data.sessions.filter((s) => !topicIds.includes(s.topicId)),
    quizzes: data.quizzes.filter((q) => !topicIds.includes(q.topicId)),
    activeTimer: data.activeTimer && data.sessions.some((s) => s.id === data.activeTimer!.sessionId && topicIds.includes(s.topicId)) ? null : data.activeTimer,
  }
  return commit(data, mid, now, 'Subject removed.', { canUndo: true })
}

export interface TopicInput {
  id?: string
  subjectId: string
  name: string
  importance: Importance
  familiarity?: Familiarity | null
}

export function saveTopic(data: AppData, input: TopicInput, now: LocalMoment): OpOutput {
  const name = input.name.trim()
  if (!name) return fail(data, 'Give the topic a name.')
  const subject = data.subjects.find((s) => s.id === input.subjectId)
  if (!subject) return fail(data, 'Pick a subject for this topic.')
  const exam = data.exams.find((e) => e.subjectId === subject.id) ?? null
  const existing = input.id ? data.topics.find((t) => t.id === input.id) : undefined
  let topics: Topic[]
  if (existing) {
    topics = data.topics.map((t) =>
      t.id === existing.id ? { ...t, name, importance: input.importance, subjectId: subject.id, examId: exam?.id ?? null } : t,
    )
  } else {
    const topic: Topic = {
      id: uid('topic'),
      subjectId: subject.id,
      examId: exam?.id ?? null,
      name,
      importance: input.importance,
      struggling: false,
      prerequisites: [],
      memory: initialMemory(input.familiarity ?? null, momentToAbs(now)),
    }
    topics = [...data.topics, topic]
  }
  return commit(data, { ...data, topics }, now, existing ? `${name} updated.` : `${name} added.`)
}

export function deleteTopic(data: AppData, topicId: string, now: LocalMoment): OpOutput {
  const mid: AppData = {
    ...data,
    topics: data.topics.filter((t) => t.id !== topicId),
    sessions: data.sessions.filter((s) => s.topicId !== topicId),
    quizzes: data.quizzes.filter((q) => q.topicId !== topicId),
    activeTimer: data.activeTimer && data.sessions.some((s) => s.id === data.activeTimer!.sessionId && s.topicId === topicId) ? null : data.activeTimer,
  }
  return commit(data, mid, now, 'Topic removed.')
}

// ---- Availability ----------------------------------------------------------------------

export function setAvailability(data: AppData, availability: Availability, now: LocalMoment): OpOutput {
  return commit(data, { ...data, availability }, now, 'Availability updated. Your plan has been recalculated.')
}

export function applyWhatIf(data: AppData, ops: readonly WhatIfOp[], now: LocalMoment): OpOutput {
  const availability = applyOps(data.availability, ops)
  return commit(data, { ...data, availability }, now, 'What-If applied. Your plan has been recalculated.')
}

export function applyCorrected(old: AppData, corrected: AppData, now: LocalMoment, note?: string): OpOutput {
  return {
    data: { ...corrected, sessions: sortSessions(corrected.sessions) },
    change: summarizeChange(old, corrected, now, "Course Correction applied. Let's work with the time you have.", { note }),
  }
}
